        }
    }

    // Part 3
    if (!hit) {
        if (l[2] == 1 && (p[2] == 1 || p[1] == 1)) {
            hit = true;
        } else if (s[2] == 1 && (p[2] == 1 || p[0] == 1)) {
            hit = true;
        } else if (r[2] == 1 && (p[2] == 1 || p[3] == 1)) {
